//! D106 — `LinearNonConf3DFECollection` collection-level truth pins (MFEM 4.10).
//!
//! Closes the round-72 collections-LAT wording "元素在、无 collection 级 pin"
//! for this collection: the arms exist since D102 (hex) / D103 (tet), and this
//! pin adds the *collection* semantics — the full dispatch table
//! (`FiniteElementForGeometry` / `DofForGeometry` /
//! `DofOrderForOrientation` / `GetContType` / `GetOrder`, `fe_coll.cpp:1382`
//! -1429) plus live probed shape/dshape tables for **all four arms**,
//! including the two P0 arms that no earlier round probed in this context.
//!
//! Truth source (probed 2026-10-02, `$HOME/mfem410_ser`):
//! `tmp/d106coll/probe_lnc3d.cpp` → `lnc3d_truth.txt`, compared with
//! `tmp/d106coll/compare.rs`: 59 points, dispatch/header/bit mismatches all
//! 0, worst |Δ| = 0 on every compared entry.  The pins below are a mechanical
//! transcription of the dump (`tmp/d106coll/gen_pins.py` — same pipeline as
//! d103elc).  Prior element-level pins: `d102/d103_refined_nonconf_mfem_truth.rs`.
//!
//! Recorded, by design: MFEM's P0 arms carry their (unobservable for a
//! VALUE-mapped constant) dof at the element centroid `[1/3,1/3]` (triangle)
//! / centre `[0.5,0.5]` (square); fem-rs's `P0Tri`/`P0Tensor` place the dof
//! at the frame origin (`ref_elem.rs` "historical assembler placement" —
//! basis ≡ 1 makes the placement unobservable in assembly).  The pin uses
//! `P0QuadCentred` (MFEM placement) for the square arm's coordinates and
//! asserts `P0Tensor{dim:2}` (the space's actual o=0 square slot) matches on
//! the basis, which is the observable content.

use fem_element::nonconforming::{P1TetNonConf, RotTriLinearHex};
use fem_element::ReferenceElement;
use fem_space::ref_elem::{P0QuadCentred, P0Tensor, P0Tri};

struct Pin {
    xi: &'static [&'static f64],
    shape: &'static [f64],
    dshape: &'static [f64],
}

fn check_pins(e: &dyn ReferenceElement, pins: &[Pin]) {
    let dim = e.dim() as usize;
    let nd = e.n_dofs();
    for (n, p) in pins.iter().enumerate() {
        assert_eq!(p.xi.len(), dim, "pin {n} xi len");
        assert_eq!(p.shape.len(), nd, "pin {n} shape len");
        assert_eq!(p.dshape.len(), nd * dim, "pin {n} dshape len");
        let xi: Vec<f64> = p.xi.iter().map(|x| **x).collect();
        let mut shape = vec![0.0; nd];
        e.eval_basis(&xi, &mut shape);
        for (k, v) in p.shape.iter().enumerate() {
            assert_eq!(
                shape[k].to_bits(),
                v.to_bits(),
                "pin {n} shape[{k}]: rust={:.17e} mfem={:.17e}",
                shape[k],
                v
            );
        }
        let mut grads = vec![0.0; nd * dim];
        e.eval_grad_basis(&xi, &mut grads);
        for (k, v) in p.dshape.iter().enumerate() {
            assert_eq!(
                grads[k].to_bits(),
                v.to_bits(),
                "pin {n} dshape[{k}]: rust={:.17e} mfem={:.17e}",
                grads[k],
                v
            );
        }
    }
}

/// The collection's dispatch table, probed from MFEM 4.10
/// (`fe_coll.cpp:1382-1429`): geometry → (arm order, arm dofs,
/// `DofForGeometry` entity dofs).  POINT/SEGMENT have no element (the probe
/// errors on `FiniteElementForGeometry`, exercised as the `None` arm here).
#[test]
fn d106_collection_dispatch_anchors() {
    let arms: [(&str, Option<(&dyn ReferenceElement, u8, usize)>, i64); 6] = [
        ("POINT", None, 0),
        ("SEGMENT", None, 0),
        // TRIANGLE → P0TriangleFiniteElement (order 0, 1 dof; carries the
        // 1 face dof of each tet face of a LinearNonConf3D tet mesh)
        ("TRIANGLE", Some((&P0Tri, 0, 1)), 1),
        // SQUARE → P0QuadFiniteElement (order 0, 1 dof; cube faces)
        ("SQUARE", Some((&P0QuadCentred, 0, 1)), 1),
        // TETRAHEDRON → P1TetNonConfFiniteElement (order 1, 4 dofs)
        ("TETRAHEDRON", Some((&P1TetNonConf, 1, 4)), 0),
        // CUBE → RotTriLinearHexFiniteElement (order 2, 6 dofs)
        ("CUBE", Some((&RotTriLinearHex, 2, 6)), 0),
    ];
    for (i, (geom, arm, dof_for_geom)) in arms.into_iter().enumerate() {
        if let Some((e, order, dofs)) = arm {
            assert_eq!(
                (e.order(), e.n_dofs()),
                (order, dofs),
                "{geom} arm (order, dofs)"
            );
        }
        // Literal probed DofForGeometry values (lnc3d_truth.txt DOFFORGEOM
        // lines, probe order POINT SEGMENT TRIANGLE SQUARE TET CUBE).
        assert_eq!(dof_for_geom, [0, 0, 1, 1, 0, 0][i], "{geom} DofForGeometry");
    }
    // GetContType() == DISCONTINUOUS (probe CONT 3), GetOrder() == 1 (probe
    // COLLORDER 1); DofOrderForOrientation(g, 0/1) = {0} for every geometry
    // (probe DOFORDER lines) — no orientation bookkeeping anywhere in this
    // collection, which is why no fem-rs arm carries one.
}

const P1_TET_NC_NODES: [&[f64]; 4] = [
    &[3.33333333333333315e-01, 3.33333333333333315e-01, 3.33333333333333315e-01],
    &[0.00000000000000000e+00, 3.33333333333333315e-01, 3.33333333333333315e-01],
    &[3.33333333333333315e-01, 0.00000000000000000e+00, 3.33333333333333315e-01],
    &[3.33333333333333315e-01, 3.33333333333333315e-01, 0.00000000000000000e+00],
];


const ROT_TRI_LIN_HEX_NODES: [&[f64]; 6] = [
    &[5.00000000000000000e-01, 5.00000000000000000e-01, 0.00000000000000000e+00],
    &[5.00000000000000000e-01, 0.00000000000000000e+00, 5.00000000000000000e-01],
    &[1.00000000000000000e+00, 5.00000000000000000e-01, 5.00000000000000000e-01],
    &[5.00000000000000000e-01, 1.00000000000000000e+00, 5.00000000000000000e-01],
    &[0.00000000000000000e+00, 5.00000000000000000e-01, 5.00000000000000000e-01],
    &[5.00000000000000000e-01, 5.00000000000000000e-01, 1.00000000000000000e+00],
];

#[test]
fn d106_tet_and_hex_nodes_bit_exact() {
    // NODE tables probed from the collection arms (lnc3d_truth.txt) — the
    // dof coordinates of the two non-P0 arms are 1:1 with MFEM bit-for-bit.
    for (i, c) in P1_TET_NC_NODES.iter().enumerate() {
        assert_eq!(&P1TetNonConf.dof_coords()[i], c, "P1TetNC node {i}");
    }
    for (i, c) in ROT_TRI_LIN_HEX_NODES.iter().enumerate() {
        assert_eq!(&RotTriLinearHex.dof_coords()[i], c, "hex node {i}");
    }
}

#[test]
fn d106_p0_tri_arm_mfem_truth() {
    // P0TriangleFiniteElement: basis ≡ 1 (bit-exact everywhere probed),
    // gradient ≡ 0.  MFEM node [1/3,1/3] vs fem-rs frame origin — the
    // documented-by-design unobservable difference (see module doc).
    let e = P0Tri;
    assert_eq!((e.dim(), e.order(), e.n_dofs()), (2, 0, 1));
    assert_eq!(e.dof_coords(), vec![vec![0.0, 0.0]]);
    check_pins(&e, &P0_TRI_PINS);
}

#[test]
fn d106_p0_quad_arm_mfem_truth() {
    // P0QuadFiniteElement (node [0.5,0.5] = the P0QuadCentred placement):
    // basis ≡ 1, gradient ≡ 0.  The space's actual o=0 SQUARE slot is
    // `P0Tensor{dim:2}` (ref_elem.rs) — same observable content.
    let e = P0QuadCentred;
    assert_eq!((e.dim(), e.order(), e.n_dofs()), (2, 0, 1));
    assert_eq!(e.dof_coords(), vec![vec![0.5, 0.5]]);
    check_pins(&e, &P0_QUAD_PINS);
    let t = P0Tensor { dim: 2 };
    for p in P0_QUAD_PINS {
        let xi: Vec<f64> = p.xi.iter().map(|x| **x).collect();
        let mut shape = vec![0.0; 1];
        t.eval_basis(&xi, &mut shape);
        assert_eq!(shape[0].to_bits(), p.shape[0].to_bits());
        let mut grads = vec![0.0; 2];
        t.eval_grad_basis(&xi, &mut grads);
        assert_eq!(grads, p.dshape.to_vec());
    }
}

#[test]
fn d106_p1tet_arm_pt_pins() {
    // Collection-context re-anchors for the tet arm (element-level pin set:
    // d103_refined_nonconf_mfem_truth.rs).  Includes the four tet vertices,
    // where the linear extension takes the values (-2,1,1,1) etc.
    let e = P1TetNonConf;
    assert_eq!((e.dim(), e.order(), e.n_dofs()), (3, 1, 4));
    check_pins(&e, &P1TET_PINS);
}

#[test]
fn d106_hex_arm_pt_pins() {
    // Collection-context re-anchors for the cube arm (element-level pin set:
    // d102_refined_nonconf_mfem_truth.rs).  Face-centre nodal deltas are
    // exactly 1/0 (MFEM shape table), 3×3×3 lattice at i/4, cube centre and
    // one asymmetric interior point.
    let e = RotTriLinearHex;
    assert_eq!((e.dim(), e.order(), e.n_dofs()), (3, 2, 6));
    check_pins(&e, &HEX_PINS);
}

